import heapq


def shortest_path(edges, start, end):
    # Check for negative weights
    for _, _, weight in edges:
        if weight < 0:
            raise ValueError("Negative edge weight detected")

    # If start == end, return (0, [start])
    if start == end:
        return (0, [start])

    # Build adjacency list
    from collections import defaultdict
    graph = defaultdict(list)
    nodes = set()
    for u, v, w in edges:
        graph[u].append((v, w))
        nodes.add(u)
        nodes.add(v)

    # Dijkstra's algorithm
    # dist[n] = shortest distance from start to n
    dist = {start: 0}
    parent = {}  # parent[n] = node n is reached from
    visited = set()

    # Priority queue: (distance, node)
    heap = [(0, start)]

    while heap:
        d, u = heapq.heappop(heap)
        if u in visited:
            continue
        visited.add(u)

        if u == end:
            # Reconstruct path
            path = []
            cur = end
            while cur is not None:
                path.append(cur)
                if cur not in parent:
                    break
                cur = parent[cur]
            path.reverse()
            return (d, path)

        for v, w in graph[u]:
            if v in visited:
                continue
            new_dist = d + w
            if v not in dist or new_dist < dist[v]:
                dist[v] = new_dist
                parent[v] = u
                heapq.heappush(heap, (new_dist, v))

    # End node not reached
    return (None, None)
